package cn.local.rainreminder;
import android.content.Context;import org.json.*;import java.time.*;import java.text.Normalizer;import java.util.*;
/** Compare dated lessons, not week-import flags; never modify saved events while previewing. */
final class CourseMerge {
 static final int NEW=0,SAME=1,DIFFERENT=2;
 static final class Match {int kind;boolean batch;List<String> details=new ArrayList<>();Set<String> keys=new TreeSet<>();String signature(){return kind+"|"+keys.toString();}Match(int k){kind=k;}}
 static String normal(String s){return Normalizer.normalize(s,Normalizer.Form.NFKC).replaceAll("[\\s\\p{Z}\\p{Cf}\uFE00-\uFE0F]+","").toLowerCase(Locale.ROOT);}
 static String room(String raw){String text=normal(CourseText.buildingLabels(Normalizer.normalize(raw,Normalizer.Form.NFKC)));java.util.regex.Matcher m=java.util.regex.Pattern.compile("([a-f])([0-9oil|]{2,5})$").matcher(text);if(m.find()&&m.group(2).matches(".*[0-9].*")){String digits=m.group(2).replace('o','0').replace('i','1').replace('l','1').replace('|','1');return text.substring(0,m.start())+m.group(1)+digits;}return text;}
 static LocalDate lastDay(JSONObject event){ZoneId zone=ZoneId.systemDefault();ZonedDateTime start=Instant.ofEpochMilli(event.optLong("start")).atZone(zone);int days=event.optInt("repeatDays");if(days<=0)return start.toLocalDate();long limit=event.optLong("until",event.optLong("start"));LocalDate until=Instant.ofEpochMilli(limit).atZone(zone).toLocalDate();long n=Math.max(0,java.time.temporal.ChronoUnit.DAYS.between(start.toLocalDate(),until)/days);ZonedDateTime last=start.plusDays(n*days);if(last.toInstant().toEpochMilli()>limit&&n>0)last=start.plusDays((n-1)*days);return last.toLocalDate();}
 static boolean sameRepeat(JSONObject incoming,JSONObject saved){return incoming.optInt("repeatDays")==0||incoming.optInt("repeatDays")==saved.optInt("repeatDays")&&lastDay(incoming).equals(lastDay(saved));}
 static String when(long time){return Instant.ofEpochMilli(time).atZone(ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("MM-dd HH:mm"));}
 static String letter(int[] points,int at){if(at>=points.length)return "结尾";String text=new String(Character.toChars(points[at]));return points[at]>='0'&&points[at]<='9'?"数字“"+text+"”":"“"+text+"”";}
 static String firstDifference(String a,String b){int[] left=normal(a).codePoints().toArray(),right=normal(b).codePoints().toArray();int at=0;while(at<left.length&&at<right.length&&left[at]==right[at])at++;return "第"+(at+1)+"个字符：识别"+letter(left,at)+"，现有"+letter(right,at);}
 static List<String> differences(JSONObject incoming,WeekTable.Item item){List<String> fields=new ArrayList<>();JSONObject e=item.event;if(!normal(incoming.optString("title")).equals(normal(e.optString("title"))))fields.add("名称不同（"+firstDifference(incoming.optString("title"),e.optString("title"))+"）");if(!room(incoming.optString("place")).equals(room(e.optString("place"))))fields.add("教室不同：识别“"+incoming.optString("place")+"”，现有“"+e.optString("place")+"”（"+firstDifference(incoming.optString("place"),e.optString("place"))+"）");if(minute(incoming.optLong("start"))!=minute(item.start))fields.add("开始日期/时间不同：识别 "+when(incoming.optLong("start"))+"，现有 "+when(item.start));if(minute(incoming.optLong("end"))!=minute(item.end))fields.add("结束日期/时间不同：识别 "+when(incoming.optLong("end"))+"，现有 "+when(item.end));if(!sameRepeat(incoming,e))fields.add("重复范围不同：识别每"+incoming.optInt("repeatDays")+"天至"+lastDay(incoming)+"，现有每"+e.optInt("repeatDays")+"天至"+lastDay(e));return fields;}
 static long minute(long n){return Math.floorDiv(n,60000L);}
 static Match compare(JSONObject incoming,List<WeekTable.Item> items,boolean batch){Match m=new Match(NEW);long from=minute(incoming.optLong("start")),end=minute(incoming.optLong("end"));for(WeekTable.Item item:items){JSONObject e=item.event;if(!e.optBoolean("course"))continue;long a=minute(item.start),b=minute(item.end);boolean sameRepeat=sameRepeat(incoming,e);if(a==from&&b==end&&normal(e.optString("title")).equals(normal(incoming.optString("title")))&&room(e.optString("place")).equals(room(incoming.optString("place")))&&sameRepeat){m.kind=SAME;m.batch=batch;m.details.clear();m.keys.clear();return m;}if(from<b&&end>a){m.kind=DIFFERENT;m.keys.add(normal(e.optString("title"))+"|"+room(e.optString("place"))+"|"+a+"|"+b);m.details.add((batch?"本批另一条：":"现有课程：")+e.optString("title")+" · "+when(item.start)+"–"+when(item.end)+(e.optString("place").isEmpty()?"":" · "+e.optString("place")));m.details.addAll(differences(incoming,item));}}return m;}
 static Match match(JSONObject incoming,JSONArray saved,JSONArray earlier){LocalDate week=Agenda.weekOf(incoming.optLong("start"));Match existing=compare(incoming,WeekTable.occurrences(saved,week),false);if(existing.kind==SAME)return existing;Match prior=compare(incoming,WeekTable.occurrences(earlier,week),true);if(prior.kind==SAME)return prior;if(existing.kind==DIFFERENT){existing.details.addAll(prior.details);existing.keys.addAll(prior.keys);return existing;}return prior;}
 static final class Plan {List<Match> matches=new ArrayList<>();int added,same,different;}
 static Plan plan(Context c,List<JSONObject> draft){Plan p=new Plan();JSONArray saved=Agenda.all(c),prior=new JSONArray();for(JSONObject e:draft){Match m=match(e,saved,prior);p.matches.add(m);if(m.kind==NEW)p.added++;else if(m.kind==SAME)p.same++;else p.different++;prior.put(e);}return p;}
 static void prepare(JSONObject e,Match match)throws Exception{if(!match.signature().equals(e.optString("_mergeAgainst"))){e.remove("_mergeChoice");e.remove("_allowOverlap");e.remove("_overlapAgainst");}e.put("_mergeAgainst",match.signature());if(!e.optBoolean("_mergeChoice")){e.put("selected",match.kind==NEW);e.remove("_allowOverlap");}}
 static void chosen(JSONObject e,Match match,boolean checked)throws Exception{e.put("_mergeChoice",true).put("selected",checked).put("_allowOverlap",checked&&match.kind==DIFFERENT);e.put("_overlapAgainst",new JSONArray(match.keys).toString());}
 static void edited(JSONObject e){clean(e);}
 static boolean approved(JSONObject e,Match match){if(!e.optBoolean("_allowOverlap"))return false;try{JSONArray entries=new JSONArray(e.optString("_overlapAgainst","[]"));Set<String> known=new HashSet<>();for(int n=0;n<entries.length();n++)known.add(entries.getString(n));return known.containsAll(match.keys);}catch(Exception invalid){return false;}}
 static void clean(JSONObject e){e.remove("_mergeAgainst");e.remove("_overlapAgainst");e.remove("_mergeChoice");e.remove("_allowOverlap");e.remove("selected");}
}